    ('5d91e81f-c555-50bf-a3d5-7d26243ecce4', '7f3b563c-aa76-5460-ab45-30c119301e9b', 0, 'em termos do que o professor vai falar.', false),
    ('fcb2d26a-a001-5638-84aa-763e3fdcc2e9', '7f3b563c-aa76-5460-ab45-30c119301e9b', 1, 'apenas como lista de páginas do livro.', false),
    ('c66ef1c8-bf67-5682-b41f-68567990d27a', '7f3b563c-aa76-5460-ab45-30c119301e9b', 2, 'sem relação com a avaliação.', false),
    ('81ee63c4-f3ff-5ef9-9dbb-bc19c7fcfde9', '7f3b563c-aa76-5460-ab45-30c119301e9b', 3, 'em termos do que o aluno será capaz de fazer ao final.', true),
    ('8bb17a7c-1d30-5f8b-9f8b-25300f171d41', '7f3b563c-aa76-5460-ab45-30c119301e9b', 4, 'de forma genérica, sem ação observável.', false),
