    ('5002da3c-ea14-5ae6-82a3-e78b96ddde56', '66b75acc-8e19-5932-b7f0-13ac47c38a8c', 1, 'parte da realidade do educando.', false),
    ('4d3e04cd-952a-50fe-a757-efbe6164fd8e', '66b75acc-8e19-5932-b7f0-13ac47c38a8c', 2, 'estimula a consciência crítica.', false),
    ('dc0f02d6-6835-58b0-aeb1-35064ff7a37c', '66b75acc-8e19-5932-b7f0-13ac47c38a8c', 3, 'dispensa o professor.', false),
    ('26de82b4-a678-5077-ab09-33e8b9ab1b10', '66b75acc-8e19-5932-b7f0-13ac47c38a8c', 4, 'trata o aluno como depósito passivo de conteúdos transmitidos pelo professor.', true),
    ('1d47fc4c-0221-5d57-942a-0400df79a29b', 'dbe46c6c-8af3-58d5-acf2-80b2eda3c723', 0, 'aprendizagem baseada em problemas.', true),
    ('3e329a49-fdde-5d43-9aa0-07e99c5de6bc', 'dbe46c6c-8af3-58d5-acf2-80b2eda3c723', 1, 'aula expositiva tradicional.', false),
    ('676273f6-1cb0-5605-8679-0bed27a1e0e6', 'dbe46c6c-8af3-58d5-acf2-80b2eda3c723', 2, 'memorização por repetição.', false),
    ('be57aa61-0609-5403-8383-1240866e4789', 'dbe46c6c-8af3-58d5-acf2-80b2eda3c723', 3, 'cópia do quadro.', false),
    ('288bee91-d04a-5f2a-b39f-c85ff5ef0517', 'dbe46c6c-8af3-58d5-acf2-80b2eda3c723', 4, 'avaliação somativa.', false),
    ('fc7723c5-2536-5f99-92f4-34dfaafac4ef', '3345ad09-6602-57bf-9c87-a2246f50c641', 0, 'O professor aplica a prova final.', false),
    ('2e94e498-9373-5f95-a00a-e3513afcee88', '3345ad09-6602-57bf-9c87-a2246f50c641', 1, 'Os alunos estudam o conteúdo básico previamente, e a aula é usada para atividades e dúvidas.', true),
    ('c44d4919-d0bf-50e2-a14f-05a3c97b29d3', '3345ad09-6602-57bf-9c87-a2246f50c641', 2, 'Os alunos fazem a recuperação.', false),
    ('fe636166-81f4-541f-9826-52ebf670123f', '3345ad09-6602-57bf-9c87-a2246f50c641', 3, 'O professor expõe todo o conteúdo pela primeira vez.', false),
    ('d8786782-3b8e-5e7d-8ec6-749af37c99c4', '3345ad09-6602-57bf-9c87-a2246f50c641', 4, 'Não há nenhum estudo.', false),
    ('d3b76ff9-bd13-544c-af77-241ba7284b32', 'ff0aa789-c645-5f11-96c5-dce624f2e615', 0, 'conteúdos proibidos pela legislação.', false),
    ('f21589ea-5842-5db7-a53c-e5c6e8a4c55b', 'ff0aa789-c645-5f11-96c5-dce624f2e615', 1, 'a parte do currículo reservada aos professores.', false),
    ('ba0dcdf9-7f9e-57fd-879f-88f7214e4ba2', 'ff0aa789-c645-5f11-96c5-dce624f2e615', 2, 'valores, atitudes e normas aprendidos na escola sem constar do currículo oficial.', true),
    ('bc912a00-4881-5604-aacf-b923f4f24026', 'ff0aa789-c645-5f11-96c5-dce624f2e615', 3, 'disciplinas optativas.', false),
