    ('58fed008-ca1f-5443-bbe3-d1ffc2840c39', '72d5f9d1-9890-5e30-bc51-52fd06b334a1', 0, 'o salário dos professores.', false),
    ('7400cef9-b143-5b2b-bc21-0b59e0d0c25e', '72d5f9d1-9890-5e30-bc51-52fd06b334a1', 1, 'o calendário escolar de cada escola.', false),
    ('1f09a29e-c2cb-5c54-b205-4098c1261ae3', '72d5f9d1-9890-5e30-bc51-52fd06b334a1', 2, 'os livros didáticos obrigatórios de cada turma.', false),
    ('1fa65e7a-7605-5bc7-85d9-215d9f559b8a', '72d5f9d1-9890-5e30-bc51-52fd06b334a1', 3, 'as aprendizagens essenciais que todos os alunos devem desenvolver na educação básica.', true),
    ('14d16549-4a4e-5405-9247-34a6d8e63b58', '72d5f9d1-9890-5e30-bc51-52fd06b334a1', 4, 'a metodologia única que todos os professores devem seguir.', false),
    ('97c7c28b-96e8-5849-84cc-bf63016584a4', 'dae5c11d-14e3-521c-a549-a6cd9d5c4482', 0, 'eliminar todas as disciplinas.', false),
    ('bc65ba90-ffcd-5c85-8369-f846cf53abce', 'dae5c11d-14e3-521c-a549-a6cd9d5c4482', 1, 'ensinar cada disciplina de forma isolada.', false),
    ('95b6b3d9-ff4d-58fc-bc8a-586bdd2372a5', 'dae5c11d-14e3-521c-a549-a6cd9d5c4482', 2, 'ter um professor para cada aluno.', false),
    ('6e8a5d3f-eb07-543e-9790-fb1e078188c0', 'dae5c11d-14e3-521c-a549-a6cd9d5c4482', 3, 'aplicar a mesma prova em todas as disciplinas.', false),
    ('a10b3335-e64e-5314-84b4-66ed6de11f31', 'dae5c11d-14e3-521c-a549-a6cd9d5c4482', 4, 'integrar conhecimentos de diferentes disciplinas em torno de um tema ou problema.', true),
    ('337b8622-a75b-544b-87e0-06da90a9d103', '0c4c2635-7a37-5554-965f-a3fdb33414fc', 0, 'diferenciação pedagógica.', true),
    ('5bca095a-c044-588b-a317-a29bf7250b62', '0c4c2635-7a37-5554-965f-a3fdb33414fc', 1, 'homogeneização da turma.', false),
    ('dbd44dd7-f41e-5514-bad6-095cb2c62831', '0c4c2635-7a37-5554-965f-a3fdb33414fc', 2, 'reprovação preventiva.', false),
