    ('d1037821-1ce2-5374-a0e8-8a7392f951d3', '7dea5bdd-4841-5ef8-bce4-9af0e5da0cce', 1, 'educação infantil, ensino fundamental e ensino médio.', true),
    ('a6185424-7de4-5348-ac38-8c36a6b99828', '7dea5bdd-4841-5ef8-bce4-9af0e5da0cce', 2, 'educação infantil e ensino superior.', false),
    ('effa9e2f-1b6a-53b8-bd40-84cf7f5a1eaa', '7dea5bdd-4841-5ef8-bce4-9af0e5da0cce', 3, 'ensino médio e pós-graduação.', false),
    ('1b71072b-16bc-5fd6-93b3-4c504518af86', '7dea5bdd-4841-5ef8-bce4-9af0e5da0cce', 4, 'apenas o ensino fundamental.', false),
    ('3072635a-8310-5f35-a651-099fab210d19', '34e544bd-e5b3-5eed-8370-99f21e1637e8', 0, 'o estágio em que a criança desenvolve a linguagem.', false),
    ('cd345e96-fb5d-5a45-bdd8-9a341f2963c0', '34e544bd-e5b3-5eed-8370-99f21e1637e8', 1, 'a fase das operações formais.', false),
    ('eb744b35-13e2-548b-aa33-43ce542cb8b5', '34e544bd-e5b3-5eed-8370-99f21e1637e8', 2, 'a distância entre o que a criança faz sozinha e o que consegue fazer com ajuda de alguém mais experiente.', true),
