    ('c2a81aef-fab6-5c3f-abcb-33775e70c27b', '457f2d23-c5dd-5331-b84e-a2c47eaa4a03', 1, 'mediação.', false),
    ('9e8d7702-3941-5af8-9cb6-8b409db6e4c2', '457f2d23-c5dd-5331-b84e-a2c47eaa4a03', 2, 'internalização.', false),
    ('d247f92d-af3a-586a-9f4c-30d8242ba360', '457f2d23-c5dd-5331-b84e-a2c47eaa4a03', 3, 'condicionamento.', false),
