    ('92dfe709-562a-5648-90dd-e3689ca619b2', '62c06ffc-06fb-53c5-9c87-eee971e559c1', 0, 'a nova informação se relaciona de forma não arbitrária com conhecimentos que o aluno já possui.', true),
    ('22bb1343-db5b-59a3-8eae-bfc6aa3444da', '62c06ffc-06fb-53c5-9c87-eee971e559c1', 1, 'o aluno memoriza o conteúdo sem compreender.', false),
    ('da7c9928-8fe4-50cd-9b43-d7f2836c2e1a', '62c06ffc-06fb-53c5-9c87-eee971e559c1', 2, 'o professor repete o conteúdo várias vezes.', false),
    ('7affa6da-b41e-5d56-8712-25bbfb1fad5f', '62c06ffc-06fb-53c5-9c87-eee971e559c1', 3, 'o aluno recebe recompensas a cada acerto.', false),
    ('1f62a58a-386b-5481-ad57-d686ba3babe4', '62c06ffc-06fb-53c5-9c87-eee971e559c1', 4, 'o conteúdo não tem relação com a vida do aluno.', false),
    ('65cb4b98-483e-5c02-973e-361f6b8c89b4', '2d73b7de-cdfc-5739-ae1e-6a328c7e6a6a', 0, 'reforço negativo.', false),
    ('88f80767-8749-5a96-ab15-4a204b4a6b5e', '2d73b7de-cdfc-5739-ae1e-6a328c7e6a6a', 1, 'reforço positivo.', true),
    ('ef3df706-ac59-57fe-826e-1372baeac613', '2d73b7de-cdfc-5739-ae1e-6a328c7e6a6a', 2, 'punição positiva.', false),
