    ('bcad8fd7-b73c-5308-bb81-2dd5e7b9c706', '8bd2304c-22d8-5881-8567-9f7b036ae317', 0, 'da maturação biológica, apenas.', false),
    ('3c7e9cb7-832d-5319-a5a8-b74bd571a9c6', '8bd2304c-22d8-5881-8567-9f7b036ae317', 1, 'de reflexos condicionados.', false),
    ('4b0d547c-961f-50ee-bac1-fb1206d101e6', '8bd2304c-22d8-5881-8567-9f7b036ae317', 2, 'das interações sociais mediadas pela linguagem e pela cultura.', true),
    ('7f793ae7-9f98-55c0-9ada-a58483c1b6f2', '8bd2304c-22d8-5881-8567-9f7b036ae317', 3, 'do isolamento do indivíduo.', false),
    ('9917e8df-6dcd-508f-857c-f107c552d269', '8bd2304c-22d8-5881-8567-9f7b036ae317', 4, 'da herança genética exclusivamente.', false),
    ('478ce87c-fe9c-5ae0-9014-e85058f5bc7d', '2ea95a81-74d3-59a1-afb9-018967896dcf', 0, 'a inteligência é única e medida apenas pelo QI.', false),
    ('8bc9e1db-bbbf-5c71-acd8-8137763bb90c', '2ea95a81-74d3-59a1-afb9-018967896dcf', 1, 'a inteligência não pode ser desenvolvida.', false),
    ('c34a0f83-d60e-5e26-bc5d-d9195366fc03', '2ea95a81-74d3-59a1-afb9-018967896dcf', 2, 'só a inteligência lógico-matemática importa na escola.', false),
    ('807bcde7-b862-59a3-981d-89706fddc650', '2ea95a81-74d3-59a1-afb9-018967896dcf', 3, 'existem diferentes tipos de inteligência, como linguística, lógico-matemática, espacial e interpessoal.', true),
    ('0c9a1e77-9c94-5364-ade8-1cc173581b8e', '2ea95a81-74d3-59a1-afb9-018967896dcf', 4, 'a inteligência depende apenas da idade.', false),
    ('d9fceacf-d9ea-5397-b24e-a87f82f357d9', '23f2ecfa-fca5-537c-ac86-8e1423596d8f', 0, 'apenas do condicionamento operante.', false),
    ('a78b6fc6-e06c-543f-a510-2d10990f9f40', '23f2ecfa-fca5-537c-ac86-8e1423596d8f', 1, 'da herança genética exclusivamente.', false),
    ('9a30ab64-b973-5510-97f5-5d67b09dac57', '23f2ecfa-fca5-537c-ac86-8e1423596d8f', 2, 'da memorização mecânica.', false),
    ('68b9a5e6-f34a-5c1d-8b52-0a21871de515', '23f2ecfa-fca5-537c-ac86-8e1423596d8f', 3, 'da punição como motivação.', false),
    ('6ed1ebe4-4bbd-5b84-ae97-b655e120f05d', '23f2ecfa-fca5-537c-ac86-8e1423596d8f', 4, 'da afetividade, integrada à cognição e ao movimento.', true),
    ('bac79c2a-7db8-56c0-b320-a8c322e33656', '409abc3c-99f4-5c2c-9232-69140ca3035f', 0, 'intrínseca.', true),
    ('5ee61c48-a0d5-5ca9-979e-13e21e9fa83d', '409abc3c-99f4-5c2c-9232-69140ca3035f', 1, 'extrínseca.', false),
    ('450b0f40-f3bf-51e2-abde-8d944ce59e5e', '409abc3c-99f4-5c2c-9232-69140ca3035f', 2, 'negativa.', false),
    ('5f177aeb-1ff8-5c7d-be48-f02bda8ddcb6', '409abc3c-99f4-5c2c-9232-69140ca3035f', 3, 'condicionada por punição.', false),
    ('6dcda3a2-8375-574d-8c70-1adce9783ac9', '409abc3c-99f4-5c2c-9232-69140ca3035f', 4, 'instrumental.', false),
    ('911e3a6e-caa2-5ef7-8e04-aabdc9b7c7c0', 'd6fee866-6bfd-59f0-b836-3ef58286fd28', 0, 'à estrutura física da escola.', false),
    ('d8bc2c2c-bb1c-5837-a5f4-af1dc00974cc', 'd6fee866-6bfd-59f0-b836-3ef58286fd28', 1, 'ao apoio temporário do professor, retirado aos poucos conforme o aluno ganha autonomia.', true),
    ('4e1e76ab-1893-5f75-a2f4-e1a118e59424', 'd6fee866-6bfd-59f0-b836-3ef58286fd28', 2, 'à punição de comportamentos indesejados.', false),
    ('49c46b10-ee72-5ca1-81a2-a158474c3e1f', 'd6fee866-6bfd-59f0-b836-3ef58286fd28', 3, 'à divisão da turma por idade.', false),
    ('33be296d-8299-5cb7-a5ce-acdf774cf3f7', 'd6fee866-6bfd-59f0-b836-3ef58286fd28', 4, 'à repetição de conteúdos até a memorização.', false),
    ('0f386c22-866a-5a8e-b194-cc94633d155c', 'ab586f81-5d77-5d73-a77a-e47e0b31c7ba', 0, 'separar alunos com deficiência em turmas exclusivas.', false),
    ('b5ceddb7-1295-563e-88c6-f99a18b77775', 'ab586f81-5d77-5d73-a77a-e47e0b31c7ba', 1, 'exigir que o aluno se adapte sozinho à escola.', false),
    ('39f7e832-2ad2-5dd2-b6f6-da1eb3243d8b', 'ab586f81-5d77-5d73-a77a-e47e0b31c7ba', 2, 'adaptar suas práticas para garantir participação e aprendizagem de todos os alunos.', true),
    ('cc1fc936-0d08-5123-a9e3-96cfc3c4a13b', 'ab586f81-5d77-5d73-a77a-e47e0b31c7ba', 3, 'matricular apenas alunos sem dificuldades.', false),
    ('cb77f089-00a5-55ee-8965-d4fa4b88d9d0', 'ab586f81-5d77-5d73-a77a-e47e0b31c7ba', 4, 'dispensar avaliações para alunos com deficiência.', false),
    ('e411fe53-f949-5994-92cf-fc728037c5c1', 'cba139e5-bcb4-5680-9cd8-cd64821816d6', 0, 'o Executivo, o Ministério Público e a Defensoria.', false),
    ('e0b8591f-5522-5a01-89f9-8a79a5bc7200', 'cba139e5-bcb4-5680-9cd8-cd64821816d6', 1, 'o Legislativo, o Judiciário e as Forças Armadas.', false),
    ('80463114-0bae-50e4-9d05-c51ff3683a61', 'cba139e5-bcb4-5680-9cd8-cd64821816d6', 2, 'o Executivo, o Legislativo e o Tribunal de Contas.', false),
