-- Recomeça o banco com um único professor e uma massa de dados de conteúdo.
-- Apaga todos os dados (contas, turmas, atividades, questões, respostas e provas). Ficam só os catálogos
-- fixos (unidade_tempo) e o histórico do Flyway.
-- Conteúdo: 10 cursos, 2 temas por curso e 11 questões por tema (220), todas publicadas e com explicação.
-- As questões são originais, no estilo do ENADE; não são itens oficiais do INEP.
-- A senha do professor fica fora do repositório (ACESSOS-LOCAIS.txt); aqui vai só o hash.

truncate table prova_pessoal_questao, prova_pessoal, resposta_pratica, resposta_tentativa, tentativa,
    comentario_atividade, atividade_questao, atividade, participacao, turma, sinalizacao, alternativa, questao,
    tema, curso, refresh_token, codigo_acesso, convite_professor, usuario cascade;

                     email_verificado) values
